/*****************************************************************************
 * 导入脚本运行的hooks，注册hooks之后自动执行脚本...
 */
import utilSrv from "./utils"
export default (function(){
    var scriptHooks = {
        onStart: {name:"start", _:[]}, //启动的时候执行逻辑
        onDomLoaded:{name:"domloaded", _:[]}, //dom加载完成的回调
        onNetSniffer: {name:"netsnifer", _:[]}, //网络拦截数据的回调
    };//定义的hooks信息
    //重置hooks监听
    scriptHooks.ScriptHookReset=()=>{
        scriptHooks.onStart._ = [];
        scriptHooks.onDomLoaded._ = [];
        scriptHooks.onNetSniffer._ = [];
    };
    //注册App启动监听
    scriptHooks.RegisterStart=(fn=()=>{})=>{
        scriptHooks.onStart._.push(fn);
    };
    //注册Dom加载完成的监听
    scriptHooks.RegisterDomLoaded=(fn=(task=null)=>{})=>{
        scriptHooks.onDomLoaded._.push(fn);
    };
    //注册网络拦截的监听
    scriptHooks.RegisterNetSniffer=(uri="*", fn=(task=null, data={}, link='')=>{})=>{
        (!uri || uri.length < 2) && (uri = '.*');
        utilSrv.NetSniffer.Append(uri); //添加监听地址
        scriptHooks.onNetSniffer._.push({uri:uri, fn:fn});
    };
    //获取与该地址匹配的回调
    scriptHooks.MatchNetSniffer=(url="") =>{
        let hooks = {name:"netsnifer", _:[]};
        let caller = scriptHooks.onNetSniffer._;
        for (let i = 0; i < caller.length; i++) {
            const uri = caller[i].uri;
            const fn = caller[i].fn;
            if (uri == "*" || uri.length < 1) {//默认
                hooks._.push(fn);
                continue;
            }
            try {
                const reg = new RegExp(uri);
                if (reg && reg.test(url)) {//地址匹配回调
                    hooks._.push(fn);
                } 
            } catch (err) {
                utilSrv.Write(utilSrv.INFO, "提取网络匹配任务...", err);
            }
        }
        utilSrv.Write(utilSrv.INFO, "提取网络匹配任务", hooks);
        return hooks;
    };
    //业务执行完成的逻辑通知
    scriptHooks.FinishTask=(task={})=>{
        utilSrv.Write(utilSrv.INFO, "任务执行完成通知...", task);
    };
    //执行hooks的业务逻辑
    scriptHooks.RunHooks=(hooks={}, task=null, data=null, link='')=>{
        utilSrv.Write(utilSrv.INFO, "运行hooks钩子信息...", hooks);
        for (let i=0; i < hooks._.length; i++) {
            hooks._[i](task, data, link);//执行hooks数据信息
        }
    };
    return scriptHooks;
})();