/*****************************************************************************
 * 脚本的基础函数库...
 */
export default (function(){
    const sUrl = process.env.S_URL;
    const isProduction = process.env.NODE_ENV == 'production';
    var utilSrv = {ERROR:1, DEBUG:2, INFO:3, _mask: isProduction? -1:5, netReqXhr:'xhr', alpha:'0123456789abcdef',maxJobTabs: 3,
        netReqFetch:"fetch", reg:/^[0-9a-z\-]{36}$/, app:"x.scraper", api:process.env.API_URL, msgHBOffScreen:'hb_offscreen', 
        msgTabNotifyMsg:'tab_notify', msgTypeDispatchTask:'dispatch_task', msgTypeCookie:'cookie', msgTypeFingerPrint:'fingerprint',
        msgTypeRunScript: 'run_script',  msgTypeApiProxy:'api_proxy', msgTypeClearCache:'clear_cache', msgTypeGetScript:'get_script', 
        msgTypeTaskCount:'task_count', msgTypeCaptureFull:'capture_full', msgTypeCaptureVisible:'capture_visible',
        msgTypeSelectedImages:'selected_images', msgTypeSelectedVideos:'selected_video', msgTypeSelectedClear:'selected_clear',
        msgTypeDownloadImages:'download_images', msgTypeDownloadVideos:'download_video', msgTypeInsertMedia:'insert_media',
        msgTypeDownloadMedia:'download_media', msgTypeAppLoginStart:'app_login_start', msgTypeWasmScraper:'wasm_scraper',
        msgTypeNetRule:'net_rule', msgTypeFFmpegDownload: 'ffmpeg_download', msgTypeOffScreenMerge:'offscreen_merge',
        msgTypeFFmpegMergeDone:'ffmpeg_merge_done', msgTypeACCEPTPORT: 'ACCEPT_PORT', msgTypePORTDELIVERY:'PORT_DELIVERY', 
        msgTypeBRIDGEREADY:'BRIDGE_READY', msgTypeBRIDGEPORT:'BRIDGE_PORT', msgTypeMEDIADATA: 'MEDIA_DATA', msgTypeSTARTMERGE: 'START_MERGE',
    };
    const _deviceId = ()=>{
        const dtStr = (new Date()).getTime().toString();
        let i, astr = dtStr.split("");
        for (i = astr.length; i < 32; i++) {
            let start = Math.floor(Math.random() * utilSrv.alpha.length);
            astr[i] = utilSrv.alpha.substring(start, start+1);
        }
        let len = astr.length;
        while(len > 1){
            let idx = Math.floor(Math.random() * len--);
            [astr[len], astr[idx]] = [astr[idx], astr[len]];
        }
        astr[12] = "4";//必须标记为4
        const s1 =astr.slice(0, 8).join("")
        const s2 =astr.slice(8, 12).join("")
        const s3 =astr.slice(12, 16).join("")
        const s4 =astr.slice(16, 20).join("")
        const s5 =astr.slice(20, 32).join("")
        return s1+"-"+s2+"-"+s3+"-"+s4+"-"+s5
    };
    utilSrv.DeviceId = async() => {//获取设备ID编号
        try {
            const result = await chrome.storage.local.get(['deviceId']);
            if (result && result.deviceId && utilSrv.reg.test(result.deviceId)) {
                return result.deviceId;
            }
            const myDeviceId = _deviceId();
            await chrome.storage.local.set({deviceId: myDeviceId});
            utilSrv.Write(utilSrv.INFO, "初始化设备ID", myDeviceId);
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "获取设备ID异常", err);
        }
        return null;
    };
    //任务执行回调业务处理逻辑data:{execute_id,data}, api地址
    utilSrv.Callback = async (params={}, apiURL="/rp-cb-execute")=>{
        //给bg发送消息通知逻辑
        utilSrv.Notify({type: utilSrv.msgTypeApiProxy,
            apiURL: apiURL, params:params});
        return null;
    };
    utilSrv.getOssUrl = (url) => {
        if (url && url.startsWith('http')) {
            return url;
        }
        return sUrl + url;
    };
    //写日志的处理逻辑
    utilSrv.Write = function(mask, ...msg) {
        if (mask > this._mask) {//关闭日志
            return
        }
        if (mask == utilSrv.ERROR) {
            console.error('Error', ...msg);//普通日志
        } else {
            let levelStr = (mask == utilSrv.DEBUG)? 'Debug':'Info';
            console.log(levelStr, ...msg);//普通日志
        }
    };
    //关闭日志的逻辑
    utilSrv.PROD = function() {
        this._mask = -1
    };
    //tab消息通知回调
    utilSrv.Notify = function(params, isTab=0) {
        window.postMessage({type: "FROM_EVAL5_TO_CONTENT",
            payload: params, isTab: isTab}, "*");
    };
    //获取记录uuid
    utilSrv.uuid = ()=>{
        var i, astr = [];
        for (i = 0; i < 36; i++) {
            let start = Math.floor(Math.random() * 0x10);
            astr[i] = utilSrv.alpha.substring(start, start+1);
        }
        astr[14] = "4";
        let start= (astr[19] & 0x3) | 0x8;
        astr[19] = utilSrv.alpha.substring(start, start+1);
        astr[8]  = astr[13] = astr[18] = astr[23] = "-";
        return astr.join("");
    },
    utilSrv.Sleep = (msec=1000)=>{
        return new Promise((resolve, _) => {
            setTimeout(() => {
                resolve('OK');
            }, msec);
        });
    },
    //普通的网络请求地址
    utilSrv.JsonRequest = async(url = '',  method = 'GET', params = {})=>{
        try {
            const response = await fetch(url, { 
                method: method, 
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(params)
            });
            let result =  await response.json();
            return JSON.parse(result);
        } catch (err) {//第三方网络请求
            utilSrv.Write(utilSrv.INFO, "第三方网络请求", err);
        }
    };
    utilSrv.Scraper = async(url = '')=>{
        try {//拦截异常的处理逻辑
            const response = await fetch(url); 
            let result = await response.text();
            return result;
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "网络请求异常", url, err);
        }
        return null;
    };
    //设置和提取地址,通过uuid确保每个界面分割开来
    utilSrv.NetSniffer = function() {
        const _snifferUrl = "_*sn*_";
        return {
            Append:(regUrl) => {
                const storage = window.localStorage;
                const result = storage.getItem(_snifferUrl);
                let regUrls = (result)? result.split(","):[];
                if (regUrls.indexOf(regUrl) == -1) {//不在里面添加
                    regUrls.push(regUrl);
                }
                storage.setItem(_snifferUrl, regUrls.join(","));
                utilSrv.Write(utilSrv.INFO, "append sniffer url", _snifferUrl, regUrl);
            },
            Get:() => {
                const storage = window.localStorage;
                return storage.getItem(_snifferUrl);
            }, 
            Remove: () => {
                const storage = window.localStorage;
                storage.removeItem(_snifferUrl);
            },
            Check:(urlStr) => {
                const storage = window.localStorage;
                const result = storage.getItem(_snifferUrl);
                utilSrv.Write(utilSrv.INFO, "sniffer check", _snifferUrl, result);
                if (!result) {//为空的情况
                   return false;
                }
                //地址匹配允许使用
                const list = result.split(",");
                for (let i = 0; i < list.length; i++) {
                    var re = new RegExp(list[i]);
                    if (re.test(urlStr)) {//正则匹配
                       return true
                    }
                }
                return false
            }
       }
    }();
    //格式化日期输出的模式
    utilSrv.DateStr = (timeStamp=0, fmt='') => {
        let d = new Date(), tmpStr = "", dateArr = [];
        (timeStamp > 0) && (d = new Date(timeStamp));
        for (let i = 0; i < fmt.length; i++) {
            let chr = fmt.substring(i, i+1);
            switch (chr) {
                case 'Y':
                    dateArr.push(d.getFullYear());
                    break;
                case 'y':
                    dateArr.push(d.getFullYear() % 100);
                    break;
                case 'm':
                case 'M':
                    tmpStr = d.getMonth()+1;
                    dateArr.push((tmpStr < 10)? '0'+tmpStr.toString():tmpStr);
                    break;
                case 'd':
                case 'D':
                    tmpStr = d.getDate();
                    dateArr.push((tmpStr < 10)? '0'+tmpStr.toString():tmpStr);
                    break;
                case 'h':
                case 'H':
                    tmpStr = d.getHours();
                    dateArr.push((tmpStr < 10)? '0'+tmpStr.toString():tmpStr);
                    break;
                case 'i':
                case 'I':
                    tmpStr = d.getMinutes();
                    dateArr.push((tmpStr < 10)? '0'+tmpStr.toString():tmpStr);
                    break;
                case 's':
                case 'S':
                    tmpStr = d.getSeconds();
                    dateArr.push((tmpStr < 10)? '0'+tmpStr.toString():tmpStr);
                    break;
                default:
                    dateArr.push(chr);
                    break;
            }
        }
        return dateArr.join(''); //数据拼接
    };
    //打开新窗口的处理逻辑
    utilSrv.PopWindow = (url='') => {
        try {
            chrome.windows.create({state:'maximized', type:'popup', url:url});
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "新窗口打开失败", err);
        }
    };
    utilSrv.isResourceSkip = (path) => {
        const resourceExts = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.svg', '.bmp', '.ico','.js', '.webm', '.ogv',
            '.css', '.xml', '.pdf','.mp4', '.m3u8', '.flv', '.mp3', '.m4s', '.zip', '.rar','.woff', '.woff2', '.ttf', '.eot']; 
        if (resourceExts.some(ext => path.includes(ext))) {
            return true;
        }
        return false;
    };
    utilSrv.Query = (link, name) => {
        if (link.startsWith('//')) {
            link = 'https:'+link;
        }
        const params = new URLSearchParams(new URL(link).search);
        return params.get(name); // 不存在返回 null
    };
    utilSrv.Sdomain = async (link) => {
        if (!link || !link.startsWith('http')) {
            const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
            if (tab && tab.url && tab.url.startsWith('http')) {
                link = tab.url;
            }
        }
        //最终未找到http地址的情况
        if (!link || !link.startsWith('http')) {
            return '';
        }
        let domain = new URL(link).hostname;
        if (domain.startsWith('www.')) {
            domain = domain.substring(4);
        }
        return domain;
    };
    utilSrv.Vdomain = async (link) => {
        let sKey = await utilSrv.Sdomain(link);
        if (!sKey) {//域名不存在的情况
            return '';
        }
        sKey = 'v_domain_'+sKey;
        return sKey;
    };
    utilSrv.videoSrc = (link, data) => {
        const regex = /https?:\/\/[^\s"'<>]+\.(?:mp4|webm|ogv|flv|m3u8)(?:\?[^\s"'<>]*)?/gi;
        const matches = data.match(regex) || [];
        const excludeRegex = /empty\d+\.(mp4|webm|ogv|flv|m3u8)$/i;
        const items = [...new Set(matches)].filter(item => {
            const filename = item.split('/').pop().split('?')[0];
            return !excludeRegex.test(filename);
        });
        if (!items || items.length < 1) {
            return [];
        }
        let title = window.document.title;
        if (window !== window.top) {
            title = window.top.document.title;
        }
        const baseUrl = new URL(link);
        return items.map((item)=>{
            try {
                const absUrl = new URL(item, baseUrl).href;
                return { src: absUrl, page:link, title:title };
            } catch (e) {
                return { src: item, page:link, title:title };
            }
        });
    };
    //采集地址数据资料
    utilSrv.videoScraper = () => {
        let link = window.location.href;
        if (window !== window.top) {//取顶级窗口地址
            try {
                link = window.top.location.href;
            } catch (err) {
                link = window.location.href;
            }
        } 
        const data  = document.body.innerHTML;
        const items = utilSrv.videoSrc(link, data);
        if (!items || items.length < 1) {
            return
        }
        const sData = {url:link, status:0, ref_type:2, items:items};  
        chrome.runtime.sendMessage({type:utilSrv.msgTypeInsertMedia, data:sData}, (response) => {
            if (chrome.runtime.lastError) { // 必须检查 lastError，否则错误会被静默吞掉
                utilSrv.Write(utilSrv.ERROR, "视频记录保存状态", chrome.runtime.lastError.message);
            } else {
                utilSrv.Write(utilSrv.INFO, "视频记录保存状态", response);
            }
        });
    };
    //开发者行为的检测
    const _devCheck = function() {
        function doCheck(a) {
            if (("" + a / a)["length"] !== 1 || a % 20 === 0) {
                (function() {}["constructor"]("debugger")())
            } else {
                (function() {}["constructor"]("debugger")())
            }
            doCheck(++a)
        }
        try {
            doCheck(0)
        } catch (err) {}
    };
    if (utilSrv._mask < utilSrv.ERROR) {//关闭日志的话
        setInterval(function() {
            _devCheck();
        }, 500);
        _devCheck();
    }
    return utilSrv
})();
